/**
 * @description
 */

let animalsName = ["xiang", "hu", "ma"];

cc.Class({
    extends: cc.Component,
    properties: {
        title: cc.Node,
        select_root: cc.Node,
        select_animals: [cc.Node],
        scratch_root: cc.Node,
        scratch_animal: cc.Node,
        scratch_items: [cc.Node],
        slots_root: cc.Node,
        symbols: [cc.Node],
        free_times: cc.Node,

        _canScratch: false,
        _endCallback: null,
    },

    startZooGame(gameInfo) {
        return new Promise(async (success)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("zoobgm");
            this.reset();
            this._endCallback = success;
            if (gameInfo.state === 0) {
                this.select_root.active = true;
                this.scratch_root.active = false;
                this.slots_root.active = false;

                this.title.getComponent(sp.Skeleton).setAnimation(0, "title02_EN", true);

                for (let i = 0; i < this.select_animals.length; i++) {
                    let animal = this.select_animals[i];
                    animal.active = true;
                    animal.getComponent(sp.Skeleton).setAnimation(0, "card_" + animalsName[i] + "_idle", true);
                    let touch = cc.find("touch", animal);
                    touch.off(cc.Node.EventType.TOUCH_END);
                    touch.on(cc.Node.EventType.TOUCH_END, async ()=>{
                        Global.SlotsSoundMgr.playEffect("sgZooClick");
                        for (let selectAnimal of this.select_animals) {
                            cc.find("touch", selectAnimal).off(cc.Node.EventType.TOUCH_END);
                        }

                        let req = {rtype: 3, choiceId: (i + 1)};
                        let result = await cc.vv.gameData.reqSubGame(req);
                        if (result.code === 200) {
                            let choiceId = result.data.choiceId;
                            let selectAnimal = cc.instantiate(this.select_animals[choiceId - 1]);
                            selectAnimal.parent = this.node;
                            selectAnimal.position = cc.v2(0, 0);
                            selectAnimal.angle = 0;
                            for (let selectAnimal1 of this.select_animals) {
                                selectAnimal1.active = false;
                            }
                            selectAnimal.getComponent(sp.Skeleton).setAnimation(0, "card_click_"+ animalsName[choiceId - 1], false);
                            selectAnimal.getComponent(sp.Skeleton).setCompleteListener(()=>{
                                selectAnimal.getComponent(sp.Skeleton).setCompleteListener(null);
                                selectAnimal.removeFromParent();
                            });

                            this.title.active = false;

                            await cc.vv.gameData.awaitTime(2);

                            this.scratchSymbol(result.data.mapInfo.gameInfo);
                        }
                    });
                }
            } else if (gameInfo.state === 1) {
                this.scratchSymbol(gameInfo);
            } else {
                this.startSlot(gameInfo);
            }
        });
    },

    scratchSymbol(gameInfo) {
        return new Promise(async (success)=>{
            this.select_root.active = false;
            this.scratch_root.active = true;
            this.title.active = true;
            this.title.getComponent(sp.Skeleton).setAnimation(0, "title01_EN", true);

            this.scratch_animal.getComponent("ImgSwitchCmp").setIndex(gameInfo.scratchCard - 1);

            this._canScratch = true;

            for (let i = 0; i < gameInfo.items.length; i++) {
                let item = gameInfo.items[i];
                let node = this.scratch_items[i];
                if (item.isOpen) {
                    cc.find("spine", node).active = false;
                    cc.find("glow", node).active = false;
                    cc.find("icon", node).getComponent("ImgSwitchCmp").setIndex(item.card - 4);
                } else {
                    cc.find("spine", node).active = true;
                    cc.find("spine", node).getComponent(sp.Skeleton).setAnimation(0, "card_idle", true);
                    cc.find("glow", node).active = false;
                    cc.find("icon", node).getComponent("ImgSwitchCmp").setIndex(item.card - 4);
                }

                node.off(cc.Node.EventType.TOUCH_END);
                node.on(cc.Node.EventType.TOUCH_END, async ()=>{
                    node.off(cc.Node.EventType.TOUCH_END);
                    if (!this._canScratch) {
                        return;
                    }

                    Global.SlotsSoundMgr.playEffect("sgZooScatch");
                    let req = {rtype: 3, choiceId: (i + 1)};
                    let result = await cc.vv.gameData.reqSubGame(req);
                    if (result.code === 200) {
                        let info = result.data.mapInfo.gameInfo;
                        let choiceId = result.data.choiceId;
                        let selectNode = this.scratch_items[choiceId - 1];
                        let selectInfo = info.items[choiceId - 1];
                        cc.find("icon", selectNode).getComponent("ImgSwitchCmp").setIndex(selectInfo.card - 4);
                        let spine = cc.find("spine", selectNode).getComponent(sp.Skeleton);
                        spine.setAnimation(0, "card_gua", false);

                        let array = this.getCards(selectInfo.card, info.items);
                        if (array.length >= 2) {
                            await cc.vv.gameData.awaitTime(1);
                            Global.SlotsSoundMgr.playEffect("sgZooMatch");
                            for (let arrayElement of array) {
                                let glow = cc.find("glow", this.scratch_items[arrayElement]);
                                glow.active = true;
                                glow.getComponent(sp.Skeleton).setAnimation(0, "win_glow", false);
                                glow.getComponent(sp.Skeleton).addAnimation(0, "win_glow", false);
                                glow.getComponent(sp.Skeleton).addAnimation(0, "win_glow", false);
                            }
                        }

                        if (info.state === 2) {
                            await cc.vv.gameData.awaitTime(1);

                            this.startSlot(info);
                        } else {
                            if (array.length >= 2) {
                                await cc.vv.gameData.awaitTime(1)
                            } else {
                                await cc.vv.gameData.awaitTime(0.5);
                            }
                            this._canScratch = true;
                        }
                    }
                });
            }
        });
    },

    async startSlot(gameInfo) {
        this.select_root.active = false;
        cc.tween(this.title)
            .to(0.5, {opacity: 0})
            .start();
        cc.tween(this.scratch_root)
            .to(0.5, {opacity: 0})
            .start();

        this.slots_root.active = true;
        this.slots_root.opacity = 0;
        cc.tween(this.slots_root)
            .to(0.5, {opacity: 255})
            .start();

        this.free_times.getComponent(cc.Label).string = (3 - gameInfo.restCnt) + "/3";

        for (let i = 0; i < this.symbols.length; i++) {
            this.symbols[i].getComponent("ImgSwitchCmp").setIndex(gameInfo.fixCards[i] - 4);
        }

        await cc.vv.gameData.awaitTime(0.5);

        this._slotsScript = cc.find("slots", this.slots_root).addComponent("Sumo_ZooSlots");
        this._restCnt = gameInfo.restCnt;

        this._slotsScript.Init();

        await cc.vv.gameData.awaitTime(1);

        cc.vv.gameData.setIsZooGame(true);
        this.reqSpin();
    },

    //全部列都停止了
    //处理停下后的中奖情况，这里多数情况需要根据自己的逻辑来处理
    async OnSpinEnd(){
        await this._slotsScript.changeWild(this._subGameData.gameInfo.slot.convertIdxs);

        this.ShowWinTrace();

        let winCoin = this._subGameData.gameInfo.slot.winCoin;
        cc.vv.gameData.GetSlotsScript().ShowBottomWin(winCoin, winCoin, false, async ()=>{
            await cc.vv.gameData.awaitTime(0.5);

            if (this._subGameData.gameInfo.isEnd) {
                await cc.vv.gameData.GetSlotsScript().popMiniGameResult(this._subGameData.gameInfo.winCoin, 2);

                cc.vv.gameData.setIsZooGame(false);
                if (this._endCallback) {
                    this._endCallback();
                }

                Global.SlotsSoundMgr.stopBgm();
                Global.SlotsSoundMgr.playNormalBgm();
            } else {
                this.reqSpin();
            }
        });
    },

    ShowWinTrace:function(){
        let allWinIdx = []

        //中奖位置
        for(let i = 0; i < this._subGameData.gameInfo.slot.zjLuXian.length; i++){
            let item = this._subGameData.gameInfo.slot.zjLuXian[i]
            for(let idx = 0; idx < item.indexs.length; idx++){
                allWinIdx[item.indexs[idx]] = 1
            }
        }

        //总
        for (const key in allWinIdx) {
            let symbol = this._slotsScript.GetSymbolByIdx(Number(key))
            if(symbol){
                symbol.playWinAnimation()
                symbol.ShowKuang()
            }
        }
    },

    //返回51请求结果
    getSubGameData(){
        return this._subGameData;
    },


    // 获取最后停止的列和卷轴
    GetLastStopSlotReel(){
        return this._slotsScript.GetLastStopReelIdx();
    },

    //点击停止按钮调用
    StopMove:function(){
        this._slotsScript.StopMove();
    },

    // 发送下一次旋转请求
    async reqSpin(){
        this._subGameData = null;
        this._restCnt--;
        this.free_times.getComponent(cc.Label).string = (3 - this._restCnt) + "/3";

        this._slotsScript.StartMove();
        let reqdata = {rtype:3};
        let result = await cc.vv.gameData.reqSubGame(reqdata);
        if(result.code === 200 && !result.spcode){
            this._subGameData = result.data.mapInfo;
            cc.vv.gameData.setMapInfo(result.data.mapInfo);

            this._slotsScript.SetSlotsResult(result.data.mapInfo.gameInfo.slot.cards);
        }
    },

    getCards(card, items) {
        let array = [];
        for (let i = 0; i < items.length; i++) {
            let item = items[i];
            if (item.card === card && item.isOpen) {
                array.push(i);
            }
        }
        return array;
    },

    reset() {
        this._restCnt = 0;
        this._endCallback = null;
    },
});