/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    ShowAntiEffect:function(bShow,name){
        if (bShow === false) {
            if (this._cfg.reelStateInfo) {
                for (let info of this._cfg.reelStateInfo) {
                    let node = cc.find(info.antiNode,this.node)
                    if(node && node.active){
                        node.active = false
                        // 既然不是循环的播放，就不需要主动停止
                        // 点立即停止的时候需要停止加速音效
                        if(this._stopRightNow){
                            cc.vv.AudioManager.stopEffectByName(info.antSound);
                        }

                    }
                }
            }
        }else{
            let node = cc.find(name,this.node)
            if(node){
                node.active = bShow
                //固定三个角一定是相同图标
                let symbol_1 = cc.vv.gameData.GetSlotsScript().getReel(0).GetSymbolByRow(0);
                let symbol_5 = cc.vv.gameData.GetSlotsScript().getReel(4).GetSymbolByRow(0);
                let symbol_21 = cc.vv.gameData.GetSlotsScript().getReel(20).GetSymbolByRow(0);
                if (symbol_1.GetShowId() === this._cfg.scatterId) {
                    symbol_1.playScatterAnimation();
                }

                if (symbol_5.GetShowId() === this._cfg.scatterId) {
                    symbol_5.playScatterAnimation();
                }

                if (symbol_21.GetShowId() === this._cfg.scatterId) {
                    symbol_21.playScatterAnimation();
                }
            }
            else{
                console.log("未找到加速节点：mask/node_anti");
            }
        }
    },

    playReelStop(){
        this._super();

        if (this._reelIdx / 5 === 0 || this._reelIdx % 5 === 4) {
            Global.SlotsSoundMgr.playEffect("reelstop")
        }
    },

    getSymbols() {
        return this._symbols;
    },
});