/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        title: cc.Node,
        spine: cc.Node,
        base_prize: cc.Node,
        result: cc.Node,
        btn_start: cc.Node,
        rate: cc.Node,

        _endCallback: null,
    },

    startBallGame(gameInfo) {
        return new Promise((success)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("ballbgm");
            this.node.active = true;
            this.reset();
            this._endCallback = success;

            this.base_prize.getComponent(cc.Label).string = Global.formatNumShort(gameInfo.startPrize, 0);
            this.title.active = true;

            this.btn_start.off(cc.Node.EventType.TOUCH_END);
            let func = async ()=>{
                this.btn_start.off(cc.Node.EventType.TOUCH_END);
                this.title.active = false;
                Global.SlotsSoundMgr.playEffect("Bonus_Bangup_LOOP");
                let req = {rtype: 3};
                let result = await cc.vv.gameData.reqSubGame(req);
                if(result.code === 200) {
                    let skin = "DJ";
                    if (result.data.mapInfo.gameInfo.mult <= 20) {
                        skin = "MJ";
                    } else if (result.data.mapInfo.gameInfo.mult <= 40) {
                        skin = "XJ";
                    } else if (result.data.mapInfo.gameInfo.mult <= 60) {
                        skin = "ZJ";
                    } else if (result.data.mapInfo.gameInfo.mult <= 80) {
                        skin = "J";
                    }
                    this.spine.getComponent(sp.Skeleton).setSkin(skin);
                    cc.vv.gameData.setMapInfo(result.data.mapInfo);
                    this.spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
                    this.spine.getComponent(sp.Skeleton).addAnimation(0, "animation1", false);
                    this.spine.getComponent(sp.Skeleton).addAnimation(0, "animation2", true);

                    await cc.vv.gameData.awaitTime(4);
                    this.result.active = true;
                    this.result.getComponent(cc.Label).string = result.data.mapInfo.gameInfo.mult + "X";
                    this.result.scale = 0;
                    cc.tween(this.result)
                        .to(0.5, {scale: 1}, {easing: "backOut"})
                        .start();

                    await cc.vv.gameData.awaitTime(0.5);

                    let particle = cc.instantiate(cc.find("fly_star", this.node.parent));
                    particle.active = true;
                    particle.parent = this.node;
                    let startPos = this.result.convertToWorldSpaceAR(cc.v2(0, 0));
                    startPos = this.node.convertToNodeSpaceAR(startPos);
                    particle.position = startPos;
                    let endPos= this.rate.convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.node.convertToNodeSpaceAR(endPos);
                    cc.tween(particle)
                        .to(0.5, {position: endPos})
                        .removeSelf()
                        .start();

                    await cc.vv.gameData.awaitTime(0.5);

                    this.rate.getComponent(cc.Label).string = result.data.mapInfo.gameInfo.mult + "X";

                    await cc.vv.gameData.awaitTime(1);

                    await cc.vv.gameData.GetSlotsScript().popMiniGameResult(result.data.mapInfo.gameInfo.winCoin, 4);

                    Global.SlotsSoundMgr.stopBgm();
                    Global.SlotsSoundMgr.playNormalBgm();
                    if (this._endCallback) {
                        this._endCallback();
                    }
                }
            }
            cc.vv.gameData.checkAutoPlay(this.btn_start, func);
            this.btn_start.on(cc.Node.EventType.TOUCH_END, async ()=>{
                this.btn_start.stopAllActions();
                await func();
            });
        });
    },

    reset() {
        this._endCallback = null;
        this.rate.getComponent(cc.Label).string = "";
        this.title.active = true;
        this.result.active = false;
        this.spine.getComponent(sp.Skeleton).clearTracks();
        this.spine.getComponent(sp.Skeleton).setToSetupPose();
    },
});