/**
 * @description
 */

let InnerRoadPoint = 5;
let OuterRoadPoint = 8;
let buildingSkins = ["ylc", "dwy", "bjl", "yxt", "mxt", "gc"];

cc.Class({
    extends: cc.Component,
    properties: {
        buildings: [cc.Node],
        roads: [cc.Node],
        chocolate_jackpot: cc.Node,
        base_prize: cc.Node,
        collect_buildings: [cc.Node],
        zhizhen: cc.Node,
        dialog_node: cc.Node,
        choose_area: cc.Node,
        next_area: cc.Node,
        next_area_icon: cc.Node,
        detail_game: cc.Node,
        detail_title: cc.Node,
        wheel_node: cc.Node,
        wheel: cc.Node,
        wheel_win: cc.Node,
        btn_back: cc.Node,

        _endCallback: null,
        _canSelect: false,
        _isInit: false,
        _curSelectBuilding: -1,
        _selectBuildingCallback: null,
    },

    openMap(mapInfo, showBtn) {
        return new Promise(async (success) => {
            this.node.active = true;
            this.node.y = cc.winSize.height;
            if (!this._isInit) {
                this._isInit = true;
                this.reset();
                this.initMap(mapInfo, showBtn);
            }
            this._endCallback = success;

            if (showBtn) {
                this.btn_back.active = true;
                this.btn_back.off("click");
                this.btn_back.on("click", () => {
                    Global.SlotsSoundMgr.playEffect("button");
                    Global.SlotsSoundMgr.playEffect("mapOut");
                    cc.tween(this.node)
                        .by(0.5, { y: cc.winSize.height })
                        .call(() => {
                            this.node.active = false;
                            cc.vv.gameData.GetSlotsScript().CanDoNextRound();
                            if (this._endCallback) {
                                this._endCallback();
                            }
                        })
                        .start();
                });
            } else {
                this.btn_back.active = false;
            }

            Global.SlotsSoundMgr.playEffect("mapIn");
            cc.tween(this.node)
                .to(0.5, { y: 0 })
                .start();

            if (!showBtn) {
                await cc.vv.gameData.awaitTime(0.5);

                if (mapInfo.state === 1) {
                    await this.popChooseArea();
                } else if (mapInfo.state === 3) {
                    let endPos = this.buildings[mapInfo.nextGame - 1].convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.zhizhen.parent.convertToNodeSpaceAR(endPos);
                    cc.tween(this.zhizhen)
                        .then(cc.jumpTo(0.5, endPos, 50, 1))
                        .call(() => {
                            cc.find("building", this.buildings[mapInfo.nextGame - 1]).color = cc.Color.WHITE;
                        })
                        .start();

                    await cc.vv.gameData.awaitTime(1);

                    await this.popDetail(mapInfo.nextGame);

                    if (this._endCallback) {
                        this._endCallback();
                    }
                } else if (mapInfo.state === 2) {
                    if (mapInfo.progressData.totalCnt >= mapInfo.progressData.needCnt && mapInfo.progressData.totalCnt !== 0) {
                        // 需要先跳
                        let road = this.getRoad(mapInfo.prevGame, mapInfo.nextGame);
                        let endPoint;
                        if (mapInfo.prevGame === 0) {
                            endPoint = cc.find("point_" + (5 - mapInfo.restStep), road);
                        } else if (mapInfo.nextGame === 6) {
                            endPoint = cc.find("point_" + mapInfo.restStep, road);
                        } else {
                            if (mapInfo.prevGame === 1) {
                                if (mapInfo.nextGame === 5) {
                                    endPoint = cc.find("point_" + mapInfo.restStep, road);
                                } else {
                                    endPoint = cc.find("point_" + (8 - mapInfo.restStep), road);
                                }
                            } else if (mapInfo.prevGame === 5) {
                                if (mapInfo.nextGame === 1) {
                                    endPoint = cc.find("point_" + (8 - mapInfo.restStep), road);
                                } else {
                                    endPoint = cc.find("point_" + mapInfo.restStep, road);
                                }
                            } else {
                                if (mapInfo.nextGame - mapInfo.prevGame > 0) {
                                    endPoint = cc.find("point_" + (8 - mapInfo.restStep), road);
                                } else {
                                    endPoint = cc.find("point_" + mapInfo.restStep, road);
                                }
                                if (mapInfo.restStep === 0) {
                                    endPoint = this.buildings[mapInfo.nextGame - 1];
                                } else if (mapInfo.restStep === OuterRoadPoint) {
                                    endPoint = this.buildings[mapInfo.prevGame - 1];
                                }
                            }
                        }
                        let endPos = endPoint.convertToWorldSpaceAR(cc.v2(0, 0));
                        endPos = this.zhizhen.parent.convertToNodeSpaceAR(endPos);

                        Global.SlotsSoundMgr.playEffect("mapJump");
                        cc.tween(this.zhizhen)
                            .then(cc.jumpTo(0.5, endPos, 50, 1))
                            .call(() => {
                                if (cc.find("finish", endPoint)) {
                                    cc.find("finish", endPoint).active = true;
                                } else {
                                    // building
                                    cc.find("building", endPoint).color = cc.Color.WHITE;
                                }
                            })
                            .start();

                        await cc.vv.gameData.awaitTime(1);

                        await this.startWheel();

                        await cc.vv.gameData.awaitTime(1);

                        cc.tween(this.node)
                            .by(0.5, { y: cc.winSize.height })
                            .call(() => {
                                if (this._endCallback) {
                                    this._endCallback();
                                }
                            })
                            .start();
                    } else {
                        await this.startWheel();

                        await cc.vv.gameData.awaitTime(1);

                        cc.tween(this.node)
                            .by(0.5, { y: cc.winSize.height })
                            .call(() => {
                                if (this._endCallback) {
                                    this._endCallback();
                                }
                            })
                            .start();
                    }
                }
            }


        });
    },

    initMap(mapInfo) {
        this.chocolate_jackpot.getComponent(cc.Label).string =
            mapInfo.superJackpot > 0 ? Global.FormatNumToComma(mapInfo.superJackpot) : "";

        if (mapInfo.totalCnt > 0) {
            this.base_prize.getComponent(cc.Label).string =
                Global.formatNumShort(Number(Global.S2P(mapInfo.totalCoin / mapInfo.totalCnt, 0)), 0);
        } else {
            this.base_prize.getComponent(cc.Label).string = "";
        }

        for (let collectBuilding of this.collect_buildings) {
            collectBuilding.active = false;
        }
        for (let i = 0; i < mapInfo.completeGame.length; i++) {
            let building = this.collect_buildings[i];
            let buildingId = mapInfo.completeGame[i];
            building.active = true;
            building.getComponent("ImgSwitchCmp").setIndex(buildingId - 1);
        }

        for (let i = 0; i < this.buildings.length; i++) {
            // By JerryWong
            let completeGame = mapInfo && mapInfo.completeGame;
            completeGame = (Array.isArray(completeGame)) ? completeGame : (completeGame && typeof completeGame === "object") ? Object.values(completeGame) : [];   
            if (completeGame.indexOf(i + 1) !== -1 || mapInfo.nextGame === (i + 1)) {
                cc.find("building", this.buildings[i]).color = cc.Color.WHITE;
            }
            // if (mapInfo.completeGame.includes(i + 1) || mapInfo.nextGame === (i + 1)) {
            //     cc.find("building", this.buildings[i]).color = cc.Color.WHITE;
            // }
            let building = this.buildings[i];
            building.off(cc.Node.EventType.TOUCH_END);
            building.on(cc.Node.EventType.TOUCH_END, () => {
                if (!this._canSelect) {
                    return;
                }
                let newInfo = cc.vv.gameData.getMapInfo();
                Global.SlotsSoundMgr.playEffect("mapLevelLight");
                if (this.canSelectBuilding(i + 1)) {
                    for (let j = 0; j < this.buildings.length; j++) {
                        // By JerryWong
                        let completeGame = mapInfo && mapInfo.completeGame;
                        completeGame = Array.isArray(completeGame) ? completeGame : (completeGame && typeof completeGame === "object") ? Object.values(completeGame) : []
                        if (completeGame.indexOf(j + 1) === -1) {
                            cc.find("building", this.buildings[j]).color = cc.Color.WHITE;
                        }
                        // if (!newInfo.completeGame.includes(j + 1)) {
                        //     cc.find("building", this.buildings[j]).color = cc.Color.GRAY;
                        // }
                    }
                    this._curSelectBuilding = i + 1;
                    cc.find("building", building).color = cc.Color.WHITE;
                    let glow = cc.find("glow", building);
                    glow.active = true;
                    glow.getComponent(sp.Skeleton).setAnimation(0, "glow2", false);
                    glow.getComponent(sp.Skeleton).setCompleteListener(async () => {
                        glow.getComponent(sp.Skeleton).setCompleteListener(null);
                        glow.active = false;
                        this.popNextArea(i + 1);
                    });
                }
            });
        }

        let buildingCfg = cc.vv.gameData.getGameCfg().buildingCfg;
        if (mapInfo.prevGame === 0) {
            // 第一个选择
            if (mapInfo.nextGame !== 0) {
                // 已经选择了
                let road = this.getRoadByName(buildingCfg[mapInfo.nextGame - 1].innerRoad);
                cc.find("lujing", road).active = true;
                cc.find("lujing", road).getComponent(sp.Skeleton).setAnimation(0, "lujing_idle", true);
                for (let i = 1; i < InnerRoadPoint; i++) {
                    let point = cc.find("point_" + i, road);
                    cc.find("finish", point).active = i <= (InnerRoadPoint - mapInfo.restStep);
                }
                if (mapInfo.restStep === InnerRoadPoint) {
                    let pos = this.buildings[5].convertToWorldSpaceAR(cc.v2(0, 0));
                    pos = this.zhizhen.parent.convertToNodeSpaceAR(pos);
                    this.zhizhen.position = pos;
                } else if (mapInfo.restStep === 0) {
                    let pos = this.buildings[mapInfo.nextGame - 1].convertToWorldSpaceAR(cc.v2(0, 0));
                    pos = this.zhizhen.parent.convertToNodeSpaceAR(pos);
                    this.zhizhen.position = pos;
                } else {
                    let pos = cc.find("point_" + (InnerRoadPoint - mapInfo.restStep), road).convertToWorldSpaceAR(cc.v2(0, 0));
                    pos = this.zhizhen.parent.convertToNodeSpaceAR(pos);
                    this.zhizhen.position = pos;
                }
            } else {
                let pos = this.buildings[5].convertToWorldSpaceAR(cc.v2(0, 0));
                pos = this.zhizhen.parent.convertToNodeSpaceAR(pos);
                this.zhizhen.position = pos;
            }
        } else {
            // 已经有上一个目的地，那就要区分下一个目的地，如果是中心房子，就是内路径，不然就是外路径
            if (mapInfo.nextGame === 6) {
                // 内路径
                let road = this.getRoadByName(buildingCfg[mapInfo.nextGame - 1].innerRoad[mapInfo.prevGame]);
                cc.find("lujing", road).active = true;
                cc.find("lujing", road).getComponent(sp.Skeleton).setAnimation(0, "lujing_idle", true);
                for (let i = 1; i < InnerRoadPoint; i++) {
                    let point = cc.find("point_" + i, road);
                    cc.find("finish", point).active = i <= (InnerRoadPoint - mapInfo.restStep);
                }
                if (mapInfo.restStep === InnerRoadPoint) {
                    let pos = this.buildings[mapInfo.prevGame - 1].convertToWorldSpaceAR(cc.v2(0, 0));
                    pos = this.zhizhen.parent.convertToNodeSpaceAR(pos);
                    this.zhizhen.position = pos;
                } else if (mapInfo.restStep === 0) {
                    let pos = this.buildings[mapInfo.nextGame - 1].convertToWorldSpaceAR(cc.v2(0, 0));
                    pos = this.zhizhen.parent.convertToNodeSpaceAR(pos);
                    this.zhizhen.position = pos;
                } else {
                    let pos = cc.find("point_" + mapInfo.restStep, road).convertToWorldSpaceAR(cc.v2(0, 0));
                    pos = this.zhizhen.parent.convertToNodeSpaceAR(pos);
                    this.zhizhen.position = pos;
                }
            } else if (mapInfo.nextGame === 0) {
                let zhizhenPoint;
                zhizhenPoint = this.buildings[mapInfo.prevGame - 1];
                let pos = zhizhenPoint.convertToWorldSpaceAR(cc.v2(0, 0));
                pos = this.zhizhen.parent.convertToNodeSpaceAR(pos);
                this.zhizhen.position = pos;
            } else {
                // 外路径
                let road = this.getRoadByName(buildingCfg[mapInfo.prevGame - 1].outerRoad[mapInfo.nextGame]);
                cc.find("lujing", road).active = true;
                cc.find("lujing", road).getComponent(sp.Skeleton).setAnimation(0, "lujing_idle", true);
                // for (let i = 1; i < OuterRoadPoint; i++) {
                //     let point = cc.find("point_" + i, road);
                //     cc.find("finish", point).active = i <= (OuterRoadPoint - mapInfo.restStep);
                // }
                let zhizhenPoint;
                if (mapInfo.prevGame === 1) {
                    if (mapInfo.nextGame === 5) {
                        zhizhenPoint = cc.find("point_" + mapInfo.restStep, road);
                        for (let i = 1; i < OuterRoadPoint; i++) {
                            let point = cc.find("point_" + i, road);
                            cc.find("finish", point).active = i >= mapInfo.restStep;
                        }
                    } else {
                        zhizhenPoint = cc.find("point_" + (OuterRoadPoint - mapInfo.restStep), road);
                        for (let i = 1; i < OuterRoadPoint; i++) {
                            let point = cc.find("point_" + i, road);
                            cc.find("finish", point).active = i <= (OuterRoadPoint - mapInfo.restStep);
                        }
                    }
                } else if (mapInfo.prevGame === 5) {
                    if (mapInfo.nextGame === 1) {
                        zhizhenPoint = cc.find("point_" + (OuterRoadPoint - mapInfo.restStep), road);
                        for (let i = 1; i < OuterRoadPoint; i++) {
                            let point = cc.find("point_" + i, road);
                            cc.find("finish", point).active = i <= (OuterRoadPoint - mapInfo.restStep);
                        }
                    } else {
                        zhizhenPoint = cc.find("point_" + mapInfo.restStep, road);
                        for (let i = 1; i < OuterRoadPoint; i++) {
                            let point = cc.find("point_" + i, road);
                            cc.find("finish", point).active = i >= mapInfo.restStep;
                        }
                    }
                } else {
                    if (mapInfo.nextGame - mapInfo.prevGame > 0) {
                        zhizhenPoint = cc.find("point_" + (OuterRoadPoint - mapInfo.restStep), road);
                        for (let i = 1; i < OuterRoadPoint; i++) {
                            let point = cc.find("point_" + i, road);
                            cc.find("finish", point).active = i <= (OuterRoadPoint - mapInfo.restStep);
                        }
                    } else {
                        zhizhenPoint = cc.find("point_" + mapInfo.restStep, road);
                        for (let i = 1; i < OuterRoadPoint; i++) {
                            let point = cc.find("point_" + i, road);
                            cc.find("finish", point).active = i >= mapInfo.restStep;
                        }
                    }
                }
                if (mapInfo.restStep === 0) {
                    zhizhenPoint = this.buildings[mapInfo.nextGame - 1];
                } else if (mapInfo.restStep === OuterRoadPoint) {
                    zhizhenPoint = this.buildings[mapInfo.prevGame - 1];
                }
                let pos = zhizhenPoint.convertToWorldSpaceAR(cc.v2(0, 0));
                pos = this.zhizhen.parent.convertToNodeSpaceAR(pos);
                this.zhizhen.position = pos;

            }
        }
    },

    async finishMiniGame(gameId, mapInfo) {
        return new Promise(async (success) => {
            let building = this.buildings[gameId - 1];
            if (gameId === 6) {
                cc.vv.gameData.getMapInfo().prevGame = 0;
                cc.vv.gameData.getMapInfo().nextGame = 0;
                this.chocolate_jackpot.getComponent(cc.Label).string = "";

                this.base_prize.getComponent(cc.Label).string = "";

                for (let collectBuilding of this.collect_buildings) {
                    collectBuilding.active = false;
                }

                for (let i = 0; i < this.buildings.length; i++) {
                    let building = this.buildings[i];
                    if (i === 5) {
                        cc.find("building", building).color = cc.Color.WHITE;
                    } else {
                        cc.find("building", building).color = cc.Color.GRAY;
                    }
                }

                await cc.vv.gameData.awaitTime(1);

                success();
            } else {
                let icon = cc.find("icon", building);
                if (icon) {
                    Global.SlotsSoundMgr.playEffect("mapLevelLight");
                    let glow = cc.find("glow", icon);
                    glow.active = true;
                    glow.getComponent(sp.Skeleton).setAnimation(0, "Map_building_wancheng", false);

                    await cc.vv.gameData.awaitTime(0.5);

                    glow.active = false;

                    let flyIcon = cc.instantiate(icon);
                    flyIcon.parent = this.node;
                    let startPos = icon.convertToWorldSpaceAR(cc.v2(0, 0));
                    startPos = this.node.convertToNodeSpaceAR(startPos);
                    flyIcon.position = startPos;
                    let collectIcon = this.collect_buildings[mapInfo.completeGame.length - 1];
                    let endPos = collectIcon.convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.node.convertToNodeSpaceAR(endPos);
                    cc.tween(flyIcon)
                        .to(0.5, { position: endPos })
                        .removeSelf()
                        .start();

                    await cc.vv.gameData.awaitTime(0.5);

                    collectIcon.active = true;
                    collectIcon.getComponent("ImgSwitchCmp").setIndex(gameId - 1);

                    Global.SlotsSoundMgr.playEffect("mapSpotLight");
                    cc.find("glow", collectIcon).active = true;
                    cc.find("glow", collectIcon).getComponent(sp.Skeleton).setAnimation(0, "Map_building_wancheng", false);
                    await cc.vv.gameData.awaitTime(0.5);

                    cc.find("glow", collectIcon).active = false;
                    success();
                }
            }
        })
    },

    canSelectBuilding(target) {
        let mapInfo = cc.vv.gameData.getMapInfo();
        let buildingCfg = cc.vv.gameData.getGameCfg().buildingCfg[target - 1];
        if (target === 6) {
            return mapInfo.completeGame.length === 5;
        } else if (mapInfo.completeGame.length === 0) {
            return true;
        } else {
            return buildingCfg.prevBuilding.includes(mapInfo.prevGame);
        }
    },

    getRoadByName(name) {
        for (let road of this.roads) {
            if (road.name === name) {
                return road;
            }
        }
        return null;
    },

    getRoad(prev, target) {
        let buildingCfg = cc.vv.gameData.getGameCfg().buildingCfg;
        if (prev === 0) {
            if (target !== 0) {
                return this.getRoadByName(buildingCfg[target - 1].innerRoad);
            }
        } else {
            if (target === 6) {
                // 内路径
                return this.getRoadByName(buildingCfg[target - 1].innerRoad[prev]);
            } else {
                // 外路径
                return this.getRoadByName(buildingCfg[prev - 1].outerRoad[target]);
            }
        }
    },

    async popChooseArea() {
        return new Promise(async (success) => {
            this._selectBuildingCallback = success;
            Global.SlotsSoundMgr.playEffect("popup");
            this.dialog_node.active = true;
            this.choose_area.active = true;
            this.choose_area.scale = 0;
            cc.tween(this.choose_area)
                .to(0.5, { scale: 1 }, { easing: "backOut" })
                .start();

            await cc.vv.gameData.awaitTime(0.5);

            let btn_start = cc.find("btn_start", this.choose_area);
            let func = () => {
                btn_start.off("click");
                Global.SlotsSoundMgr.playEffect("button");

                cc.tween(this.choose_area)
                    .to(0.5, { scale: 0 }, { easing: "backIn" })
                    .call(() => {
                        this.choose_area.active = false;
                        this.dialog_node.active = false;
                        this._canSelect = true;

                        let mapInfo = cc.vv.gameData.getMapInfo();
                        if (mapInfo.completeGame.length === 5) {
                            // 只能选最后一个
                            let building = this.buildings[5];
                            let glow = cc.find("glow", building);
                            glow.active = true;
                            glow.getComponent(sp.Skeleton).setSkin(buildingSkins[5]);
                            glow.getComponent(sp.Skeleton).setAnimation(0, "glow1", true);
                        } else {
                            for (let i = 0; i < 5; i++) {
                                let building = this.buildings[i];
                                if (this.canSelectBuilding(i + 1)) {
                                    let glow = cc.find("glow", building);
                                    glow.active = true;
                                    glow.getComponent(sp.Skeleton).setSkin(buildingSkins[i]);
                                    glow.getComponent(sp.Skeleton).setAnimation(0, "glow1", true);
                                }
                            }
                        }

                        // success();
                    })
                    .start();
            }
            cc.vv.gameData.checkAutoPlay(btn_start, func);
            btn_start.on("click", () => {
                btn_start.stopAllActions();
                func();
            });
        });
    },

    async popNextArea(target) {
        Global.SlotsSoundMgr.playEffect("popup");
        this.dialog_node.active = true;
        this.next_area.active = true;
        this.next_area.scale = 0;
        cc.tween(this.next_area)
            .to(0.5, { scale: 1 }, { easing: "backOut" })
            .start();

        this.next_area_icon.getComponent("ImgSwitchCmp").setIndex(target - 1);

        await cc.vv.gameData.awaitTime(0.5);

        let btn_no = cc.find("mapBgPopBoard/btn_no", this.next_area);
        btn_no.on("click", () => {
            btn_no.off("click");
            Global.SlotsSoundMgr.playEffect("button");

            this._canSelect = true;
            this._curSelectBuilding = -1;
            cc.tween(this.next_area)
                .to(0.5, { scale: 0 }, { easing: "backIn" })
                .call(() => {
                    this.next_area.active = false;
                    this.dialog_node.active = false;
                    if (cc.vv.gameData.getMapInfo().completeGame.length === 5) {
                        // 只能选最后一个
                        let building = this.buildings[5];
                        let glow = cc.find("glow", building);
                        glow.active = true;
                        glow.getComponent(sp.Skeleton).setSkin(buildingSkins[5]);
                        glow.getComponent(sp.Skeleton).setAnimation(0, "glow1", true);
                    } else {
                        for (let i = 0; i < 5; i++) {
                            let building = this.buildings[i];
                            if (this.canSelectBuilding(i + 1)) {
                                let glow = cc.find("glow", building);
                                glow.active = true;
                                glow.getComponent(sp.Skeleton).setSkin(buildingSkins[i]);
                                glow.getComponent(sp.Skeleton).setAnimation(0, "glow1", true);
                            }
                        }
                    }
                })
                .start();
        });

        let btn_yes = cc.find("mapBgPopBoard/btn_yes", this.next_area);
        btn_yes.on("click", async () => {
            btn_yes.off("click");
            Global.SlotsSoundMgr.playEffect("button");
            this._canSelect = false;

            let req = { rtype: 1, choiceGameId: this._curSelectBuilding };
            let result = await cc.vv.gameData.reqSubGame(req);
            if (result.code === 200) {
                cc.vv.gameData.setMapInfo(result.data.mapInfo);
                cc.vv.gameData.GetSlotsScript().updateTargetSkin(result.data.mapInfo.nextGame);
                cc.tween(this.next_area)
                    .to(0.5, { scale: 0 }, { easing: "backIn" })
                    .call(async () => {
                        this.next_area.active = false;
                        this.dialog_node.active = false;
                        let building = this.buildings[result.data.choiceGameId - 1];
                        cc.find("building", building).color = cc.Color.WHITE;
                        let glow = cc.find("glow", building);
                        glow.active = true;
                        glow.getComponent(sp.Skeleton).setAnimation(0, "glow1", true);

                        for (let i = 0; i < this.buildings.length; i++) {
                            let bu = this.buildings[i];
                            if (i !== result.data.choiceGameId - 1) {
                                cc.find("glow", bu).active = false;
                                cc.find("building", building).color = cc.Color.GRAY;
                            }
                        }

                        let road = this.getRoad(result.data.mapInfo.prevGame, result.data.mapInfo.nextGame);
                        for (let i = 1; i < OuterRoadPoint; i++) {
                            let point = cc.find("point_" + i, road);
                            if (point) {
                                cc.find("finish", point).active = false;
                            }
                        }

                        let lujing = cc.find("lujing", road);
                        lujing.active = true;
                        lujing.getComponent(sp.Skeleton).setAnimation(0, "lujing_intro", false);
                        lujing.getComponent(sp.Skeleton).addAnimation(0, "lujing_idle", true);

                        await cc.vv.gameData.awaitTime(1);

                        await this.startWheel();

                        await cc.vv.gameData.awaitTime(1);

                        cc.tween(this.node)
                            .by(0.5, { y: cc.winSize.height })
                            .call(() => {
                                if (this._endCallback) {
                                    this._endCallback();
                                }

                                if (this._selectBuildingCallback) {
                                    this._selectBuildingCallback();
                                    this._selectBuildingCallback = null;
                                }
                            })
                            .start();
                    })
                    .start();
            }
        });
    },

    async popDetail(target) {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.playEffect("popup");
            this.dialog_node.active = true;
            this.detail_game.active = true;
            this.detail_game.scale = 0;
            cc.tween(this.detail_game)
                .to(0.5, { scale: 1 }, { easing: "backOut" })
                .start();

            this.detail_title.getComponent("ImgSwitchCmp").setIndex(target - 1);

            await cc.vv.gameData.awaitTime(0.5);

            let self = this;
            let func = function () {
                btn_start.off("click");
                Global.SlotsSoundMgr.playEffect("button");

                cc.tween(self.detail_game)
                    .to(0.5, { scale: 0 }, { easing: "backIn" })
                    .call(() => {
                        self.detail_game.active = false;
                        self.dialog_node.active = false;
                        success();
                    })
                    .start();
            }
            let btn_start = cc.find("btn_start", this.detail_game);
            cc.vv.gameData.checkAutoPlay(btn_start, func)
            btn_start.on("click", () => {
                btn_start.stopAllActions();
                func();
            });
        });
    },

    async startWheel() {
        return new Promise(async (success) => {
            this.wheel_node.active = true;
            Global.SlotsSoundMgr.playEffect("wheelshow");
            this.wheel_win.active = false;
            cc.find("wheel_node/btn_spin/grey", this.wheel_node).active = false;
            let root = cc.find("wheel_node", this.wheel_node);
            root.scale = 0;
            cc.tween(root)
                .to(0.5, { scale: 1 }, { easing: "backOut" })
                .start();

            this.wheel.angle = 0;
            let spin_spine = cc.find("wheel_node/btn_spin/spine", this.wheel_node).getComponent(sp.Skeleton);
            spin_spine.node.color = cc.Color.WHITE;
            spin_spine.setAnimation(0, "spin_idle", true);

            let btn_spin = cc.find("wheel_node/btn_spin", this.wheel_node);
            let func = async () => {
                btn_spin.off("click");
                Global.SlotsSoundMgr.playEffect("wheelclick");
                cc.find("grey", btn_spin).active = true;
                spin_spine.setAnimation(0, "spin_click", false);
                spin_spine.setCompleteListener(() => {
                    spin_spine.setCompleteListener(null);
                    spin_spine.node.color = cc.Color.GRAY;
                });

                let req = { rtype: 2 };
                let result = await cc.vv.gameData.reqSubGame(req);
                if (result.code === 200) {
                    cc.vv.gameData.setMapInfo(result.data.mapInfo);
                    cc.vv.gameData.GetSlotsScript().updateCollectProgress(result.data.mapInfo, false);
                    await new Promise((suc) => {
                        Global.SlotsSoundMgr.playEffect("wheelspin");
                        let angle = result.data.idx * 45 - 2160;
                        console.log(angle);
                        let action = cc.rotateBy(6, angle).easing(cc.easeSineInOut());
                        this.wheel.runAction(cc.sequence(action, cc.callFunc(() => {
                            Global.SlotsSoundMgr.playEffect("wheelstop");
                            suc();
                        })));
                    });

                    this.wheel_win.active = true;

                    await cc.vv.gameData.awaitTime(2);

                    Global.SlotsSoundMgr.playEffect("wheelshow");
                    cc.tween(root)
                        .to(0.5, { scale: 0 }, { easing: "backIn" })
                        .call(() => {
                            this.wheel_node.active = false;
                            success();
                        })
                        .start();
                }
            }
            cc.vv.gameData.checkAutoPlay(btn_spin, func);
            btn_spin.on("click", async () => {
                btn_spin.stopAllActions();
                await func();
            });
        });
    },

    reset() {
        for (let i = 0; i < this.buildings.length; i++) {
            cc.find("building", this.buildings[i]).color = cc.Color.GRAY;
            cc.find("glow", this.buildings[i]).active = false;
        }

        for (let road of this.roads) {
            cc.find("lujing", road).active = false;
            for (let i = 0; i < 7; i++) {
                let point = cc.find("point_" + (i + 1), road);
                if (point) {
                    cc.find("finish", point).active = false;
                }
            }
        }

        this._endCallback = null;
        this._canSelect = false;
    },
});