/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        base_prize: cc.Node,
        rate: cc.Node,
        free_times: cc.Node,

        _endCallback: null,
        _restCnt: 0,
    },

    startBallonGame(gameInfo) {
        return new Promise(async (success)=>{
            this.node.active = true;
            this.reset();
            this._slotsScript = cc.find("slots", this.node).addComponent("Sumo_BallonSlots");
            this._endCallback = success;
            this._restCnt = gameInfo.restCnt;

            this.base_prize.getComponent(cc.Label).string = Global.formatNumShort(gameInfo.startPrize, 0);
            this.rate.getComponent(cc.Label).string = "";

            this._slotsScript.Init();

            await cc.vv.gameData.awaitTime(1);

            cc.vv.gameData.setIsBallonGame(true);
            this.reqSpin();
        });
    },

    reset() {
        this._restCnt = 0;
        this._endCallback = null;
    },

    generateBallon(resultRate) {
        let rates = [10, 20, 25, 30, 100];
        let skins = ["hong", "huang", "lan", "zi"];
        let resultBallonIndex = Math.floor(Math.random() * 5 + 5);
        for (let i = 0; i < 10; i++) {
            let ballon = cc.instantiate(cc.find("ballon", this.node));
            ballon.active = true;
            if (i === resultBallonIndex) {
                cc.find("rate_down", ballon).getComponent(cc.Label).string = resultRate + "X";
                cc.find("rate_up", ballon).getComponent(cc.Label).string = resultRate + "X";
            } else {
                let rate = rates[Math.floor(Math.random() * 5)]
                cc.find("rate_down", ballon).getComponent(cc.Label).string = rate + "X";
                cc.find("rate_up", ballon).getComponent(cc.Label).string = rate + "X";
            }

            ballon.parent = this.node;
            ballon.y = -cc.winSize.height / 2 - 200;
            ballon.x = Math.random() > 0.5 ? Math.random() * 200 - 300 : Math.random() * 200 + 100;
            ballon.getComponent(sp.Skeleton).setSkin(skins[Math.floor(Math.random() * 4)]);
            ballon.getComponent(sp.Skeleton).setAnimation(0, "qiqiu_idle", true);
            if (i === resultBallonIndex) {
                cc.tween(ballon)
                    .delay(i * 0.5)
                    .to(2, {y: 250})
                    .call(()=>{
                        ballon.getComponent(sp.Skeleton).setAnimation(0, "qiqiu_win", true);
                    })
                    .delay(6 - i * 0.5)
                    .call(async ()=>{
                        Global.SlotsSoundMgr.playEffect("sgCollect");
                        let particle = cc.instantiate(cc.find("fly_star", this.node.parent));
                        particle.active = true;
                        particle.parent = this.node;
                        particle.position = ballon.position;
                        let endPos = this.rate.convertToWorldSpaceAR(cc.v2(0, 0));
                        endPos = this.node.convertToNodeSpaceAR(endPos);
                        cc.tween(particle)
                            .to(0.5, {position: endPos})
                            .removeSelf()
                            .start();

                        await cc.vv.gameData.awaitTime(0.5);

                        let fly_star_end = cc.find("fly_star_end", this.rate.parent);
                        fly_star_end.active = true;
                        fly_star_end.getComponent(sp.Skeleton).setAnimation(0, "multi_end3", false);

                        await cc.vv.gameData.awaitTime(0.5);

                        fly_star_end.active = false;

                        this.rate.scale = 1;
                        this.rate.getComponent(cc.Label).string = resultRate + "X";
                        cc.tween(this.rate)
                            .to(0.1, {scale: 1.1})
                            .to(0.1, {scale: 1})
                            .start();

                        await cc.vv.gameData.awaitTime(0.2);
                    })
                    .to(0.5, {opacity: 0})
                    .removeSelf()
                    .start();
            } else {
                cc.tween(ballon)
                    .delay(i * 0.5)
                    .to(3, {y: cc.winSize.height / 2 + 200})
                    .removeSelf()
                    .start();
            }
        }
    },

    //全部列都停止了
    //处理停下后的中奖情况，这里多数情况需要根据自己的逻辑来处理
    async OnSpinEnd(){
        this.ShowWinTrace();

        let winCoin = this._subGameData.gameInfo.slot.winCoin * this._subGameData.gameInfo.slot.mult;
        cc.vv.gameData.GetSlotsScript().ShowBottomWin(winCoin, winCoin, false, async ()=>{
             await cc.vv.gameData.awaitTime(0.5);

             if (this._subGameData.gameInfo.isEnd) {
                 await cc.vv.gameData.GetSlotsScript().popMiniGameResult(this._subGameData.gameInfo.winCoin, 5);

                 cc.vv.gameData.setIsBallonGame(false);
                 if (this._endCallback) {
                    this._endCallback();
                 }
             } else {
                 this.reqSpin();
             }
        });
    },

    ShowWinTrace:function(){
        let allWinIdx = []

        //中奖位置
        for(let i = 0; i < this._subGameData.gameInfo.slot.zjLuXian.length; i++){
            let item = this._subGameData.gameInfo.slot.zjLuXian[i]
            for(let idx = 0; idx < item.indexs.length; idx++){
                allWinIdx[item.indexs[idx]] = 1
            }
        }

        //总
        for (const key in allWinIdx) {
            let symbol = this._slotsScript.GetSymbolByIdx(Number(key))
            if(symbol){
                symbol.playWinAnimation()
                symbol.ShowKuang()
            }
        }


    },

    //返回51请求结果
    getSubGameData(){
        return this._subGameData;
    },

    // getMaxReelIdx(type, col){
    //     let reelList = this._slotsScript.getLastStopReel();
    //     return reelList[col];
    // },

    // 获取最后停止的列和卷轴
    GetLastStopSlotReel(){
        return this._slotsScript.GetLastStopReelIdx();
    },

    //点击停止按钮调用
    StopMove:function(){
        this._slotsScript.StopMove();
    },

    // 发送下一次旋转请求
    async reqSpin(){
        this._subGameData = null;
        this._restCnt--;
        this.free_times.getComponent(cc.Label).string = (3 - this._restCnt) + "/3";

        this.rate.getComponent(cc.Label).string = "";
        this._slotsScript.StartMove();
        let reqdata = {rtype:3};
        let result = await cc.vv.gameData.reqSubGame(reqdata);
        if(result.code === 200 && !result.spcode){
            this._subGameData = result.data.mapInfo;
            cc.vv.gameData.setMapInfo(result.data.mapInfo);

            this.generateBallon(this._subGameData.gameInfo.mults[2 - this._restCnt]);
            this._slotsScript.SetStopTime(6);
            this._slotsScript.SetSlotsResult(result.data.mapInfo.gameInfo.slot.cards);
        }
    },
});