/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        jackpot: cc.Node,
        jackpot_effect: cc.Node,
        base_prize: cc.Node,
        rate: cc.Node,
        layout: cc.Node,

        _successCallback: null,
        _canSelect: false,
        _haveOpenReward: null,
    },

    async startPickGame(mapInfo) {
        return new Promise((success)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("sgbgm");
            this.reset();
            this._successCallback = success;
            let gameInfo = mapInfo.gameInfo;

            this.jackpot.getComponent(cc.Label).string = Global.FormatNumToComma(mapInfo.superJackpot);
            this.base_prize.getComponent(cc.Label).string = Global.formatNumShort(gameInfo.startPrize, 0);
            this.rate.getComponent(cc.Label).string = gameInfo.mult > 0 ? gameInfo.mult + "X" : "";

            this._canSelect = true;


            for (let i = 0; i < 16; i++) {
                let item = cc.find("box_" + (i + 1), this.layout);
                let info = gameInfo.items[i];
                let spine = cc.find("GC_box_choice", item).getComponent(sp.Skeleton);
                if (info.isOpen) {
                    this._haveOpenReward.push(i);
                    let skin = info.type === 3 ? "jackpot" : (info.mult + "X" + (info.type === 2 ? "2" : ""));
                    spine.setSkin(skin);
                    spine.setAnimation(0, "box_click", false);
                } else {
                    spine.setAnimation(0, "box_idle", true);
                }

                item.on(cc.Node.EventType.TOUCH_END, async ()=>{
                    if (!this._canSelect) {
                        return;
                    }

                    if (this._haveOpenReward.indexOf(i) !== -1) {
                        return;
                    }

                    this._canSelect = false;
                    Global.SlotsSoundMgr.playEffect("sgFactory");
                    let req = {rtype:3, choiceId: (i + 1)};
                    let result = await cc.vv.gameData.reqSubGame(req);
                    if (result.code === 200) {
                        let choiceId = result.data.choiceId;
                        cc.vv.gameData.setMapInfo(result.data.mapInfo);
                        let newInfo = result.data.mapInfo.gameInfo.items[choiceId - 1];
                        this._haveOpenReward.push(choiceId - 1);

                        let selectItem = cc.find("box_" + choiceId, this.layout);
                        let selectSpine = cc.find("GC_box_choice", selectItem).getComponent(sp.Skeleton);
                        let skin = newInfo.type === 3 ? "jackpot" : (newInfo.mult + "X" + (newInfo.type === 2 ? "2" : ""));
                        selectSpine.setSkin(skin);
                        selectSpine.setAnimation(0, "box_click", false);

                        await cc.vv.gameData.awaitTime(0.5);

                        Global.SlotsSoundMgr.playEffect("sgCollect");
                        let particle = cc.instantiate(cc.find("fly_star", this.node.parent));
                        particle.active = true;
                        particle.parent = this.node;
                        let startPos = selectItem.convertToWorldSpaceAR(cc.v2(0, 0));
                        startPos = this.node.convertToNodeSpaceAR(startPos);
                        particle.position = startPos;
                        let endPos;
                        if (newInfo.type === 3) {
                            // super jackpot
                            this.endGame(result.data.mapInfo.gameInfo);
                            endPos = this.jackpot.convertToWorldSpaceAR(cc.v2(0, 0));
                            endPos = this.node.convertToNodeSpaceAR(endPos);
                        } else {
                            endPos = this.rate.convertToWorldSpaceAR(cc.v2(0, 0));
                            endPos = this.node.convertToNodeSpaceAR(endPos);
                        }
                        cc.tween(particle)
                            .to(0.5, {position: endPos})
                            .removeSelf()
                            .start();

                        await cc.vv.gameData.awaitTime(0.5);

                        if (newInfo.type === 3) {
                            this.jackpot_effect.active = true;
                            this.jackpot_effect.getComponent(sp.Skeleton).setAnimation(0, "K_glow", false);
                            this.jackpot_effect.getComponent(sp.Skeleton).addAnimation(0, "K_glow2", true);

                            await cc.vv.gameData.awaitTime(1);

                            await cc.vv.gameData.GetSlotsScript().popSuperJackpotDialog(mapInfo.superJackpot);

                            await cc.vv.gameData.GetSlotsScript().popMiniGameResult(result.data.mapInfo.gameInfo.winCoin, 6);

                            if (this._successCallback) {
                                this._successCallback();
                            }
                        } else {
                            let fly_star_end = cc.find("fly_star_end", this.rate.parent);
                            fly_star_end.active = true;
                            fly_star_end.getComponent(sp.Skeleton).setAnimation(0, "multi_end3", false);

                            await cc.vv.gameData.awaitTime(0.5);

                            fly_star_end.active = false;

                            this.rate.scale = 1;
                            this.rate.getComponent(cc.Label).string = result.data.mapInfo.gameInfo.mult + "X";
                            cc.tween(this.rate)
                                .to(0.1, {scale: 1.1})
                                .to(0.1, {scale: 1})
                                .start();

                            if (result.data.mapInfo.gameInfo.isEnd) {
                                this.endGame(result.data.mapInfo.gameInfo);

                                await cc.vv.gameData.awaitTime(1);

                                await cc.vv.gameData.GetSlotsScript().popMiniGameResult(result.data.mapInfo.gameInfo.winCoin, 6);

                                if (this._successCallback) {
                                    this._successCallback();
                                }

                                Global.SlotsSoundMgr.stopBgm();
                                Global.SlotsSoundMgr.playNormalBgm();
                            } else {
                                this._canSelect = true;
                            }
                        }
                    }
                });
            }
        });

    },

    async endGame(gameInfo) {
        for (let j = 1; j < 17; j++) {
            // 所有的翻过来
            let info = gameInfo.items[j - 1];
            let item = cc.find("box_" + j, this.layout);
            let spine = cc.find("GC_box_choice", item).getComponent(sp.Skeleton);
            let skin = info.type === 3 ? "jackpot" : (info.mult + "X" + (info.type === 2 ? "2" : ""));
            if (!info.isOpen) {
                spine.setSkin(skin);
                spine.setAnimation(0, "box_grey", false);
            }
        }
    },

    reset() {
        // 重置所有金币节点
        for (let i = 1; i < 17; i++) {
            let item = cc.find("box_" + i, this.layout);
            let spine = cc.find("GC_box_choice", item).getComponent(sp.Skeleton);
            spine.setAnimation(0, "box_idle", true);
        }

        // 重置变量
        this._successCallback = null;
        this._canSelect = false;
        this._haveOpenReward = [];
    },
});