/**
 * @description
 */

cc.Class({
    extends: cc.Component,

    properties: {
        bonus_bg: cc.Node,
        mult_root: cc.Node,
        top_level: cc.Node,
        choice_tips: cc.Node,
        choice_icon: cc.Node,
        level_layout: cc.Node,
        level_child: cc.Node,
        arrow_root: cc.Node,
        arrow: cc.Node,
        mult_glow: cc.Node,
        tips_glow: cc.Node,
        bg_quanpan: cc.Node,


        _exitCallBack:null,
        _curCollectNum: 0,
        _subGameData: null,
    },

    Init(bonusGame){
        cc.vv.gameData.getDeskInfo().bonusGame = bonusGame;
        this.bonus_bg.active = true;
        this.node.active = true;
        this.bg_quanpan.active = false;
        if (!this.node.getComponent("Sumo_BonusSlots")) {
            this._slotsScript = this.node.addComponent("Sumo_BonusSlots");
        }
        cc.find("right", this.top_level).getComponent(cc.Label).string = bonusGame.prizeMap[24];
        cc.vv.gameData.GetSlotsScript().node.active = false;
        for (let i = 3; i < bonusGame.prizeMap.length - 1; i++) {
            let rate = bonusGame.prizeMap[i];

                let node = cc.instantiate(this.level_child);
                node.parent = this.level_layout;
                node.active = true;
                cc.find("left", node).getComponent(cc.Label).string = (i + 1);
                cc.find("right", node).getComponent(cc.Label).string = rate;

        }

        this.choice_icon.getComponent("ImgSwitchCmp").setIndex(bonusGame.card - 4);
        this.calculateLayoutAndTipsPos(bonusGame.idxs.length);

        this._curCollectNum = bonusGame.idxs.length;

        for (let i = 1; i < 5; i++) {
            cc.find("mult_" + i, this.arrow_root).getComponent(cc.Label).string =
                bonusGame.prizeMap[24] * bonusGame.mults[i] + "X";
        }
    },

    /**
     * 计算位置
     * @param num 图标数量
     */
    calculateLayoutAndTipsPos(num) {
        if (num >= 21) {
            this.choice_tips.y = (num - 21) * 40;
            this.level_layout.y = -13 * 40 - 160;
        } else if (num >= 8) {
            this.choice_tips.y = 0;
            this.level_layout.y = (8 - num) * 40 - 160;
        } else {
            this.choice_tips.y = (num - 8) * 40;
            this.level_layout.y = -160;
        }
    },

    reset() {
        this.level_layout.removeAllChildren();
        this.level_layout.y = 0;
        this._exitCallBack = null;
        this._curCollectNum = 0;
    },

    // 触发
    async startBonusGame(bonusGame){
        return new Promise(async (success)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("bgbgm");
            this.reset();
            this.Init(bonusGame);
            this._exitCallBack = success;

            cc.vv.gameData.setIsBonusGame(true);
            this._slotsScript.Init();
            this._slotsScript.reconnectInitSymbol();

            await cc.vv.gameData.awaitTime(1);

            this.reqSpin();
        })

    },

    exitBonusGame(){
        cc.vv.gameData.setIsBonusGame(false);
    },

    //点击停止按钮调用
    StopMove:function(){
        this._slotsScript.StopMove();
    },

    //全部列都停止了
    //处理停下后的中奖情况，这里多数情况需要根据自己的逻辑来处理
    async OnSpinEnd(){
        if (this._subGameData.spIdx) {
            let symbol = this._slotsScript.GetSymbolByIdx(this._subGameData.spIdx);
            symbol.playTriggerMultAnimation();

            Global.SlotsSoundMgr.playEffect("arrowUp");
            this.arrow.active = true;
            let skins = ["lv", "lan", "zi", "hong"];
            this.arrow.getComponent(sp.Skeleton).setSkin(skins[this._subGameData.currMult - 2]);
            this.arrow.getComponent(sp.Skeleton).setAnimation(0, "jiantou_02", false);
            this.arrow.y = -160;
            cc.tween(this.arrow)
                .to(0.5, {y: 160})
                .call(()=>{
                    this.arrow.active = false;
                })
                .start();

            for (let i = 0; i < this.level_layout.childrenCount; i++) {
                let child = this.level_layout.children[i];
                cc.tween(child)
                    .delay(0.1 * i + 0.2)
                    .call(()=>{
                        // 变色
                        let color = [cc.color(52, 206, 13), cc.color(12, 152, 236), cc.color(245, 60, 238), cc.color(239, 41, 37),];
                        cc.find("left", child).color = color[this._subGameData.currMult - 2];
                        cc.find("equal", child).color = color[this._subGameData.currMult - 2];
                        cc.find("right", child).color = color[this._subGameData.currMult - 2];
                    })
                    .to(0.1, {scale: 1.1})
                    .to(0.1, {scale: 1})
                    .start();
            }

            await cc.vv.gameData.awaitTime(1.5);
        }

        //开始收集
        await this.moveTips(this._subGameData.idxs.length);

        for (let idx of this._subGameData.idxs) {
            let symbol = this._slotsScript.GetSymbolByIdx(idx);
            symbol.showBonusKuang();
        }

        if(this._subGameData.isEnd){
            Global.SlotsSoundMgr.stopBgm();
            // Global.SlotsSoundMgr.playEffect("music_HowlingMoon_spin_respin_Over");
            if (this._subGameData.idxs.length === 25) {
                // 集满了
                Global.SlotsSoundMgr.playEffect("bgAll");
                this.bg_quanpan.active = true;
                this.bg_quanpan.getComponent(sp.Skeleton).setAnimation(0, "BG_quanpan_intro", false);
                this.bg_quanpan.getComponent(sp.Skeleton).addAnimation(0, "BG_quanpan_idle", true);
                await cc.vv.gameData.awaitTime(1);
            }
            await cc.vv.gameData.awaitTime(1);

            await cc.vv.gameData.GetSlotsScript().popBonusResult(this._subGameData.winCoin);

            cc.vv.gameData.GetSlotsScript().cutSceneBonus();

            await cc.vv.gameData.awaitTime(1.5);


            //4.切屏
            this.exitBonusGame();
            cc.find("slots", this.node.parent).active = true;
            this.bonus_bg.active = false;
            this.node.active = false;

            cc.vv.gameData.AddCoin(this._subGameData.winCoin);

            cc.vv.gameData.GetSlotsScript().ShowBottomWin(this._subGameData.winCoin,
                this._subGameData.winCoin, true, ()=>{
                    if(this._exitCallBack){
                        this._exitCallBack();
                    }
                    Global.SlotsSoundMgr.stopBgm();
                    Global.SlotsSoundMgr.playNormalBgm();
                    cc.vv.gameData.GetSlotsScript().CanDoNextRound();
                });
        } else {
            await cc.vv.gameData.awaitTime(1);

            this.reqSpin();
        }

    },

    async moveTips(targetNum) {
        this.mult_glow.active = true;
        for (let i = 0; i < targetNum - this._curCollectNum; i++) {
            Global.SlotsSoundMgr.playEffect("stripUp");
            if (this.choice_tips.y < 0) {
                cc.tween(this.choice_tips)
                    .call(()=>{
                        this.tips_glow.active = true;
                        this.tips_glow.getComponent(sp.Skeleton).setAnimation(0, "glow", false);
                    })
                    .by(0.3, {y: 40})
                    .start();
            } else if (this.level_layout.y === -13 * 40 - 160) {
                cc.tween(this.choice_tips)
                    .call(()=>{
                        this.tips_glow.active = true;
                        this.tips_glow.getComponent(sp.Skeleton).setAnimation(0, "glow", false);
                    })
                    .by(0.3, {y: 40})
                    .start();
            } else {
                cc.tween(this.level_layout)
                    .call(()=>{
                        this.tips_glow.active = true;
                        this.tips_glow.getComponent(sp.Skeleton).setAnimation(0, "glow", false);
                    })
                    .by(0.3, {y: -40})
                    .start();
            }
            await cc.vv.gameData.awaitTime(0.4);
        }
        this._curCollectNum = targetNum;
        this.mult_glow.active = false;
    },

    //返回51请求结果
    getSubGameData(){
        return this._subGameData;
    },

    // getMaxReelIdx(type, col){
    //     let reelList = this._slotsScript.getLastStopReel();
    //     return reelList[col];
    // },

    // 获取最后停止的列和卷轴
    GetLastStopSlotReel(){
        return this._slotsScript.GetLastStopReelIdx();
    },

    // 发送下一次旋转请求
    async reqSpin(){
        this._subGameData = null;
        this._curTimes--;

        this._slotsScript.StartMove(cc.vv.gameData.getDeskInfo().bonusGame.idxs);
        let reqdata = {rtype:5};
        let result = await cc.vv.gameData.reqSubGame(reqdata);
        if(result.code === 200 && !result.spcode){
            this._subGameData = result.data.bonusGame;
            cc.vv.gameData.getDeskInfo().bonusGame = result.data.bonusGame;
            // cc.vv.gameData.setBonusGame(this._subGameData);

            this._slotsScript.setSpinResult(result.data.bonusGame);
        }
    },
});