/**
 * @description
 */

let cakeCfg = [4, 4, 4, 4, 3, 3];

cc.Class({
    extends: cc.Component,
    properties: {
        base_prize: cc.Node,
        rate: cc.Node,
        bowl: cc.Node,
        bowl_left: cc.Node,
        items: [cc.Node],
        tips: cc.Node,

        _endCallback: null,
        _canTouch: false,
    },


    async startIceGame(gameInfo) {
        return new Promise((success)=>{
            this.node.active = true;
            this.reset();
            this._endCallback = success;

            this.base_prize.getComponent(cc.Label).string = Global.formatNumShort(gameInfo.startPrize, 0);
            this.rate.getComponent(cc.Label).string = gameInfo.mult > 0 ? gameInfo.mult + "X" : "";

            for (let i = 0; i < 5; i++) {
                let bowl = cc.find("bowl_" + (i + 1), this.bowl_left);
                bowl.active = i < gameInfo.restCnt;
            }

            for (let i = 0; i < this.items.length; i++) {
                let item = this.items[i];
                let boxLength = cakeCfg[i];
                let collectNum = gameInfo.currIceCreams.filter((value)=>{return value === (i + 1)}).length;
                for (let j = 0; j < boxLength; j++) {
                    let box = cc.find("multi_box_" + (j + 1), item);
                    cc.find("select", box).active = j < collectNum;
                    cc.find("select", box).getComponent(sp.Skeleton).setAnimation(0, "kuang_jingzhen", true);
                }
            }

            this._canTouch = true;
            let touch = cc.find("touch", this.bowl);
            touch.off(cc.Node.EventType.TOUCH_END);
            let func = async ()=>{
            // cc.find("touch", this.bowl).on(cc.Node.EventType.TOUCH_END, async ()=>{
                if (!this._canTouch) {
                    return;
                }

                Global.SlotsSoundMgr.playEffect("sgIceMake");
                this._canTouch = false;
                let req = {rtype: 3};
                let result = await cc.vv.gameData.reqSubGame(req);
                if(result.code === 200){
                    let info = result.data.mapInfo.gameInfo;
                    cc.vv.gameData.setMapInfo(result.data.mapInfo);
                    this.tips.active = false;
                    let leftBowl = cc.find("bowl_" + (info.restCnt + 1), this.bowl_left);
                    leftBowl.getComponent(sp.Skeleton).setAnimation(0, "bowl_end", false);
                    leftBowl.getComponent(sp.Skeleton).setCompleteListener(()=>{
                        leftBowl.getComponent(sp.Skeleton).setCompleteListener(null);
                        leftBowl.active = false;
                    });

                    this.bowl.getComponent(sp.Skeleton).setSkin("dianxin0" + info.currIceCream);
                    this.bowl.getComponent(sp.Skeleton).setAnimation(0, "bowl_click", false);
                    this.bowl.getComponent(sp.Skeleton).addAnimation(0, "result_idle", true);

                    await cc.vv.gameData.awaitTime(2);

                    Global.SlotsSoundMgr.playEffect("sgIceCollect");
                    let cake = cc.find("cake", this.items[info.currIceCream - 1]);
                    let particle = cc.instantiate(cc.find("fly_star", this.node.parent));
                    particle.active = true;
                    particle.parent = this.node;
                    particle.position = this.bowl.position;
                    let endPos = cake.convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.node.convertToNodeSpaceAR(endPos);
                    cc.tween(particle)
                        .to(0.5, {position: endPos})
                        .removeSelf()
                        .start();

                    await cc.vv.gameData.awaitTime(0.5);

                    let fly_star_end = cc.find("fly_star_end", cake);
                    fly_star_end.active = true;
                    fly_star_end.getComponent(sp.Skeleton).setAnimation(0, "fly_star_end", false);

                    await cc.vv.gameData.awaitTime(0.5);

                    fly_star_end.active = false;

                    console.log(info.currIceCreams.filter((value)=>{return value === info.currIceCream;}).length);
                    let box = cc.find("multi_box_" + (info.currIceCreams.filter((value)=>{return value === info.currIceCream;}).length),
                        this.items[info.currIceCream - 1]);
                    let select = cc.find("select", box);
                    select.active = true;
                    select.getComponent(sp.Skeleton).setAnimation(0, "kuang", false);
                    select.getComponent(sp.Skeleton).addAnimation(0, "kuang_jingzhen", true);

                    Global.SlotsSoundMgr.playEffect("sgCollect");
                    particle = cc.instantiate(cc.find("fly_star", this.node.parent));
                    particle.active = true;
                    particle.parent = this.node;
                    let position = box.convertToWorldSpaceAR(cc.v2(0, 0));
                    position = this.node.convertToNodeSpaceAR(position);
                    particle.position = position;
                    if (info.currIceCreams.filter((value)=>{return value === info.currIceCream;}).length === cakeCfg[info.currIceCream - 1]) {
                        // 加次数
                        let newBowl = cc.find("bowl_" + info.restCnt, this.bowl_left);
                        endPos = newBowl.convertToWorldSpaceAR(cc.v2(0, 0));
                        endPos = this.node.convertToNodeSpaceAR(endPos);
                        cc.tween(particle)
                            .to(0.5, {position: endPos})
                            .removeSelf()
                            .start();

                        await cc.vv.gameData.awaitTime(0.5);

                        for (let i = 0; i < 5; i++) {
                            let bowl = cc.find("bowl_" + (i + 1), this.bowl_left);
                            if (!bowl.active && i < info.restCnt) {
                                bowl.active = true;
                                bowl.getComponent(sp.Skeleton).setAnimation(0, "bowl_jingzhen", true);
                            }
                        }

                        await cc.vv.gameData.awaitTime(0.2);
                    } else {
                        // 加倍数
                        endPos = this.rate.convertToWorldSpaceAR(cc.v2(0, 0));
                        endPos = this.node.convertToNodeSpaceAR(endPos);
                        cc.tween(particle)
                            .to(0.5, {position: endPos})
                            .removeSelf()
                            .start();

                        await cc.vv.gameData.awaitTime(0.5);

                        fly_star_end = cc.find("fly_star_end", this.rate.parent);
                        fly_star_end.active = true;
                        fly_star_end.getComponent(sp.Skeleton).setAnimation(0, "multi_end3", false);

                        await cc.vv.gameData.awaitTime(0.5);

                        fly_star_end.active = false;

                        this.rate.scale = 1;
                        this.rate.getComponent(cc.Label).string = info.mult + "X";
                        cc.tween(this.rate)
                            .to(0.1, {scale: 1.1})
                            .to(0.1, {scale: 1})
                            .start();

                        await cc.vv.gameData.awaitTime(0.2);
                    }

                    if (info.isEnd) {
                        await cc.vv.gameData.awaitTime(1);

                        await cc.vv.gameData.GetSlotsScript().popMiniGameResult(info.winCoin, 3);

                        if (this._endCallback) {
                            this._endCallback();
                        }
                    } else {
                        this.tips.active = true;
                        this.bowl.getComponent(sp.Skeleton).setAnimation(0, "resultTobowl", false);
                        this.bowl.getComponent(sp.Skeleton).addAnimation(0, "bowl_idle", true);

                        await cc.vv.gameData.awaitTime(0.5);

                        this._canTouch = true;
                        cc.vv.gameData.checkAutoPlay(touch, func);
                    }
                }
            };
            cc.vv.gameData.checkAutoPlay(touch, func);
            touch.on(cc.Node.EventType.TOUCH_END, async ()=>{
                touch.stopAllActions();
                await func();
            });
        });
    },

    reset() {
        this._endCallback = null;
        this._canTouch = false;
    },
});