    async updateCollectProgress(mapInfo, isAdd) {
        let progress = cc.find("collect_node/progress", this.node);
        cc.find("collect_node/collect_tips/num", this.node).getComponent(cc.Label).string =
            mapInfo.progressData.needCnt - mapInfo.progressData.totalCnt < 0 ? 0 : mapInfo.progressData.needCnt - mapInfo.progressData.totalCnt;
        let percent = mapInfo.progressData.totalCnt / mapInfo.progressData.needCnt > 1 ?
            1 : mapInfo.progressData.totalCnt / mapInfo.progressData.needCnt;
        if (isAdd) {
            let lizi = cc.find("collect", progress);
            lizi.active = true;
            lizi.getComponent(sp.Skeleton).setAnimation(0, "bar_move_lizi", false);
            lizi.getComponent(sp.Skeleton).setCompleteListener(() => {
                lizi.getComponent(sp.Skeleton).setCompleteListener(null);
                lizi.active = false;
            })

            cc.tween(progress.getComponent(cc.ProgressBar))
                .to(0.5, {progress: percent})
                .start();

            cc.tween(lizi)
                .to(0.5, {x: percent * progress.width})
                .start();
        } else {
            progress.getComponent(cc.ProgressBar).progress = percent;
        }
    },

