/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {},

    playScatterAnimation() {
        if(this._showNode){
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node){
            this._state = "win";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true

                aniNode.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,"Scatter_100to140",false);
                    nodeSp.addAnimation(0, "Scatter_140", true);
                }
        }
    },

    playTriggerFreeAnimation() {
        if(this._showNode){
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node){
            this._state = "win";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true

            aniNode.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx*10;
            let nodeSp = topShowNode.getComponent(sp.Skeleton)
            if(nodeSp){
                nodeSp.setAnimation(0,"Scatter_02_140",false);
                nodeSp.addAnimation(0, "Scatter_140to100", false);
                nodeSp.addAnimation(0, "Scatter_02", true);
            }
        }
    },

    //显示随机符号
    ShowRandomSymbol:function(){
        if (!cc.vv.gameData.isBonusGame()) {
            this._super();
        } else {
            let randVal;
            let card = cc.vv.gameData.GetBonusGame().card;
            let randomSymbols = [card, 14, 14, 14, 14];
            let randIdx = Global.random(1,randomSymbols.length)
            randVal = randomSymbols[randIdx-1]
            this.ShowById(randVal);
        }
    },

    ShowNormal:function(){
        this._super();
        this._showNode.scale = 1;
    },

    async playMysteryAnimation(mysteryId) {
        this._showNode.stopAllActions()
        //记录原始缩放
        this._showNode.scale = 1;
        cc.tween(this._showNode)
            .to(0.5, {scale: 0})
            .start();

        await cc.vv.gameData.awaitTime(0.5);

        this._showNode.scale = 1;
        this.ShowById(mysteryId);
        this._showNode.scale = 0;
        cc.tween(this._showNode)
            .to(0.5, {scale: 1})
            .start()
    },

    playTriggerBonusAnimation() {
        if(this._showNode){
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node){
            this._state = "win";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].win_ani && cfg.symbol[id].win_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                aniNode.scale = 1.2;
                cc.find("BG_yingfen", topShowNode).active = true;

                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].win_ani.name,true)
                }
            }
        }
    },

    playTriggerMultAnimation() {
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "trigger";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].trigger_ani.name !== ""){
                this.node.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].trigger_ani.name,false);
                    nodeSp.setCompleteListener(()=>{
                        nodeSp.setCompleteListener(null);
                        cc.tween(this._showNode)
                            .to(0.5, {scale: 0})
                            .call(()=>{
                                Global.SlotsSoundMgr.playEffect("reelbg");
                                this.ShowById(cc.vv.gameData.GetBonusGame().card);
                            })
                            .to(0.5, {scale: 1})
                            .start();
                    });
                }
            }
        }
    },

    async changeWild() {
        return new Promise(async (success)=>{
            Global.SlotsSoundMgr.playEffect("sgZooDW");
            if (this._showNode) {
                cc.tween(this._showNode)
                    .to(0.4, {scale: 0})
                    .start();

                await cc.vv.gameData.awaitTime(0.4);

                this.ShowById(101);

                cc.tween(this._showNode)
                    .to(0.4, {scale: 1})
                    .start();

                await cc.vv.gameData.awaitTime(0.4);

                success();
            }
        });

    },

    showBonusKuang() {
        if(this._showNode){
            cc.find("BG_yingfen", this._showNode).active = true;
        }
    },
});