/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        base_prize: cc.Node,
        rate: cc.Node,
        wheels: [cc.Node],
        wheel_win: cc.Node,
        boxes: [cc.Node],
        wheel_spin: cc.Node,
        btn_spin: cc.Node,

        _endCallback: null,
        _canSpin: false,
    },

    startWheelGame(gameInfo) {
        return new Promise(async (success)=>{
            this.reset();
            this._endCallback = success;
            this._result = [0, 0, 0, 0, 0, 0];
            this._angles = [0, 0, 0];
            this._canSpin = true;

            this.base_prize.getComponent(cc.Label).string = Global.formatNumShort(gameInfo.startPrize, 0);

            for (let i = 0; i < gameInfo.currStep; i++) {
                let result = gameInfo.finalColorComb[i];
                for (let resultElement of result) {
                    this._result[resultElement - 1]++;
                }
            }
            for (let i = 0; i < this._result.length; i++) {
                let num = this._result[i];
                let box = this.boxes[i];
                for (let j = 0; j < num; j++) {
                    cc.find("reward_" + (j + 1), box).active = true;
                }
            }

            this.btn_spin.off(cc.Node.EventType.TOUCH_END);
            let func = async ()=>{
                if (!this._canSpin) {
                    return;
                }

                Global.SlotsSoundMgr.playEffect("sgSkyWheelClick");
                this._canSpin = false;
                this.wheel_spin.getComponent(sp.Skeleton).setAnimation(0, "spin_jingzhen", true);
                this.wheel_spin.color = cc.Color.GRAY;
                let req = {rtype: 3};
                let result = await cc.vv.gameData.reqSubGame(req);
                if (result.code === 200) {
                    cc.vv.gameData.setMapInfo(result.data.mapInfo);

                    Global.SlotsSoundMgr.playEffect("sgSkyWheelspin");
                    let animations = ["win_B", "win_M", "win_S"];
                    let colors = ["huang", "hong", "zi", "lan", "lv", "qing"];
                    let suffix = ["_b", "_m", "_s"];
                    let info = result.data.mapInfo.gameInfo;
                    let comb = info.finalColorComb[info.currStep - 1];
                    for (let i = 0; i < comb.length; i++) {
                        let index = this.getResultIndex(i, comb[i]);
                        await this._rotateWheel(index, i);
                        cc.find("gray", this.wheels[i]).active = true;

                        this.wheel_win.active = true;
                        this.wheel_win.getComponent(sp.Skeleton).setSkin("win_" + colors[comb[i] - 1] + suffix[i]);
                        this.wheel_win.getComponent(sp.Skeleton).setAnimation(0, animations[i], false);
                        await cc.vv.gameData.awaitTime(1);
                        this.wheel_win.active = false;
                    }

                    for (let i = 0; i < 3; i++) {
                        Global.SlotsSoundMgr.playEffect("sgCollect");
                        let startNode = cc.find("start", this.wheels[i]);
                        let particle = cc.instantiate(cc.find("fly_star", this.node.parent));
                        particle.active = true;
                        particle.parent = this.node;
                        let startPos = startNode.convertToWorldSpaceAR(cc.v2(0, 0));
                        startPos = this.node.convertToNodeSpaceAR(startPos);
                        particle.position = startPos;
                        this._result[comb[i] - 1]++;
                        let endNode = cc.find("reward_" + this._result[comb[i] - 1], this.boxes[comb[i] - 1]);
                        let endPos = endNode.convertToWorldSpaceAR(cc.v2(0, 0));
                        endPos = this.node.convertToNodeSpaceAR(endPos);
                        cc.tween(particle)
                            .to(0.5, {position: endPos})
                            .call(async ()=>{
                                endNode.active = true;
                                // let effect = cc.find("effect", this.boxes[comb[i] - 1]);
                                // effect.active = true;
                                // effect.getComponent(sp.Skeleton).setAnimation(0,
                                //     comb[i] - 1 === 1 ? "red_win" : (colors[comb[i]- 1] + "_win"), false);
                                // await cc.vv.gameData.awaitTime(0.5);
                                // effect.active = false;
                            })
                            .removeSelf()
                            .start();

                        await cc.vv.gameData.awaitTime(1);
                    }

                    if (info.isEnd) {
                        for (let box of this.boxes) {
                            for (let i = 0; i < 3; i++) {
                                cc.find("reward_" + (i + 1), box).active = false;
                            }
                        }

                        let startNode = this.boxes[info.finalColorId - 1];
                        let particle = cc.instantiate(cc.find("fly_star", this.node.parent));
                        particle.active = true;
                        particle.parent = this.node;
                        let startPos = startNode.convertToWorldSpaceAR(cc.v2(0, 0));
                        startPos = this.node.convertToNodeSpaceAR(startPos);
                        particle.position = startPos;
                        let endPos = this.rate.convertToWorldSpaceAR(cc.v2(0, 0));
                        endPos = this.node.convertToNodeSpaceAR(endPos);
                        cc.tween(particle)
                            .to(0.5, {position: endPos})
                            .removeSelf()
                            .start();

                        await cc.vv.gameData.awaitTime(0.5);

                        let fly_star_end = cc.find("fly_star_end", this.rate.parent);
                        fly_star_end.active = true;
                        fly_star_end.getComponent(sp.Skeleton).setAnimation(0, "multi_end3", false);

                        await cc.vv.gameData.awaitTime(0.5);

                        fly_star_end.active = false;

                        this.rate.scale = 1;
                        this.rate.getComponent(cc.Label).string = info.mult + "X";
                        cc.tween(this.rate)
                            .to(0.1, {scale: 1.1})
                            .to(0.1, {scale: 1})
                            .start();

                        await cc.vv.gameData.awaitTime(0.2);

                        await cc.vv.gameData.GetSlotsScript().popMiniGameResult(info.winCoin, 1);

                        cc.vv.gameData.AddCoin(info.winCoin, true);

                        if (this._endCallback) {
                            this._endCallback();
                        }
                    } else {
                        this.wheel_spin.getComponent(sp.Skeleton).setAnimation(0, "spin_idle", true);
                        this.wheel_spin.color = cc.Color.WHITE;
                        for (let wheel of this.wheels) {
                            cc.find("gray", wheel).active = false;
                        }
                        this._canSpin = true;
                        cc.vv.gameData.checkAutoPlay(this.btn_spin, func);
                    }
                }
            }
            cc.vv.gameData.checkAutoPlay(this.btn_spin, func);
            this.btn_spin.on(cc.Node.EventType.TOUCH_END, async ()=>{
                this.btn_spin.stopAllActions();
                await func();
            })
        });
    },

    getResultIndex(wheelIndex, color) {
        let cfg = cc.vv.gameData.getGameCfg().wheelCfg[wheelIndex];
        return cfg.indexOf(color);
    },

    async _rotateWheel(endIndex, wheelIndex) {
        return new Promise(async (success)=>{

            let angle = (endIndex - this._angles[wheelIndex]) * 36 - 2160;
            this._angles[wheelIndex] = endIndex;

            let action = cc.rotateBy(4, angle).easing(cc.easeSineInOut());
            cc.find("wheel", this.wheels[wheelIndex]).runAction(cc.sequence(action, cc.callFunc(()=>{
                success();
            })));
        });
    },

    reset() {
        for (let wheel of this.wheels) {
            cc.find("wheel", wheel).angle = 0;
            cc.find("gray", wheel).active = false;
        }
        for (let box of this.boxes) {
            for (let i = 0; i < 3; i++) {
                cc.find("reward_" + (i + 1), box).active = false;
            }
        }

        this.wheel_win.active = false;

        this.wheel_spin.getComponent(sp.Skeleton).setAnimation(0, "spin_idle", true);
        this.wheel_spin.color = cc.Color.WHITE;

        this._endCallback = null;
        this._canSpin = false;
    }
});